// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.15;

interface IGovernorBravoEventsAndErrors {
    // --- ERRORS ---------------------------------------------------------

    // Admin Errors
    error GovernorBravo_OnlyAdmin();
    error GovernorBravo_OnlyPendingAdmin();
    error GovernorBravo_OnlyVetoGuardian();
    error GovernorBravo_AlreadyInitialized();
    error GovernorBravo_NotActive();
    error GovernorBravo_AddressZero();
    error GovernorBravo_InvalidDelay();
    error GovernorBravo_InvalidPeriod();
    error GovernorBravo_InvalidGracePeriod();
    error GovernorBravo_InvalidThreshold();
    error GovernorBravo_InvalidCalldata();
    error GovernorBravo_Emergency_SupplyTooLow();
    error GovernorBravo_NotEmergency();
    // Proposal Errors
    error GovernorBravo_Proposal_ThresholdNotMet();
    error GovernorBravo_Proposal_LengthMismatch();
    error GovernorBravo_Proposal_NoActions();
    error GovernorBravo_Proposal_TooManyActions();
    error GovernorBravo_Proposal_AlreadyActive();
    error GovernorBravo_Proposal_AlreadyPending();
    error GovernorBravo_Proposal_IdCollision();
    error GovernorBravo_Proposal_IdInvalid();
    error GovernorBravo_Proposal_TooEarly();
    error GovernorBravo_Proposal_AlreadyActivated();
    // Voting Errors
    error GovernorBravo_InvalidSignature();
    error GovernorBravo_Vote_Closed();
    error GovernorBravo_Vote_InvalidType();
    error GovernorBravo_Vote_AlreadyCast();
    // Workflow Errors
    error GovernorBravo_Queue_FailedProposal();
    error GovernorBravo_Queue_AlreadyQueued();
    error GovernorBravo_Queue_BelowThreshold();
    error GovernorBravo_Queue_VetoedProposal();
    error GovernorBravo_Execute_NotQueued();
    error GovernorBravo_Execute_BelowThreshold();
    error GovernorBravo_Execute_VetoedProposal();
    error GovernorBravo_Cancel_AlreadyExecuted();
    error GovernorBravo_Cancel_WhitelistedProposer();
    error GovernorBravo_Cancel_AboveThreshold();
    error GovernorBravo_Veto_AlreadyExecuted();

    // --- EVENTS ------------------------------------------------------------------

    /// @notice An event emitted when a new proposal is created
    event ProposalCreated(
        uint256 id,
        address proposer,
        address[] targets,
        uint256[] values,
        string[] signatures,
        bytes[] calldatas,
        uint256 startBlock,
        string description
    );

    /// @notice Event emitted when a proposal's voting period is activated
    event ProposalVotingStarted(uint256 id);

    /// @notice An event emitted when a vote has been cast on a proposal
    /// @param voter The address which casted a vote
    /// @param proposalId The proposal id which was voted on
    /// @param support Support value for the vote. 0=against, 1=for, 2=abstain
    /// @param votes Number of votes which were cast by the voter
    /// @param reason The reason given for the vote by the voter
    event VoteCast(
        address indexed voter,
        uint256 proposalId,
        uint8 support,
        uint256 votes,
        string reason
    );

    /// @notice An event emitted when a proposal has been vetoed
    event ProposalVetoed(uint256 id);

    /// @notice An event emitted when a proposal has been canceled
    event ProposalCanceled(uint256 id);

    /// @notice An event emitted when a proposal has been queued in the Timelock
    event ProposalQueued(uint256 id, uint256 eta);

    /// @notice An event emitted when a proposal has been executed in the Timelock
    event ProposalExecuted(uint256 id);

    /// @notice An event emitted when the voting delay is set
    event VotingDelaySet(uint256 oldVotingDelay, uint256 newVotingDelay);

    /// @notice An event emitted when the voting period is set
    event VotingPeriodSet(uint256 oldVotingPeriod, uint256 newVotingPeriod);

    /// @notice Emitted when implementation is changed
    event NewImplementation(address oldImplementation, address newImplementation);

    /// @notice Emitted when proposal threshold is set
    event ProposalThresholdSet(uint256 oldProposalThreshold, uint256 newProposalThreshold);

    /// @notice Emitted when pendingAdmin is changed
    event NewPendingAdmin(address oldPendingAdmin, address newPendingAdmin);

    /// @notice Emitted when pendingAdmin is accepted, which means admin is updated
    event NewAdmin(address oldAdmin, address newAdmin);

    /// @notice Emitted when whitelist account expiration is set
    event WhitelistAccountExpirationSet(address account, uint256 expiration);

    /// @notice Emitted when the whitelistGuardian is set
    event WhitelistGuardianSet(address oldGuardian, address newGuardian);

    /// @notice Emitted when the vetoGuardian is set
    event VetoGuardianSet(address oldGuardian, address newGuardian);
}

src/external/governance/abstracts/Govern.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.15;

import {IgOHM} from "src/interfaces/IgOHM.sol";
import {ITimelock} from "../interfaces/ITimelock.sol";
import "src/Kernel.sol";

abstract contract GovernorBravoDelegatorStorage {
    // --- PROXY STATE VARIABLES ---------------------------------------------------

    /// @notice Administrator for this contract
    address public admin;

    /// @notice Pending administrator for this contract
    address public pendingAdmin;

    /// @notice Active brains of Governor
    address public implementation;
}

/**
 * @title Storage for Governor Bravo Delegate
 * @notice For future upgrades, do not change GovernorBravoDelegateStorageV1. Create a new
 * contract which implements GovernorBravoDelegateStorageV1 and following the naming convention
 * GovernorBravoDelegateStorageVX.
 */
abstract contract GovernorBravoDelegateStorageV1 is GovernorBravoDelegatorStorage {
    // --- DATA STRUCTURES ---------------------------------------------------------

    struct Proposal {
        /// @notice Unique id for looking up a proposal
        uint256 id;
        /// @notice Creator of the proposal
        address proposer;
        /// @notice The proposal balance threshold that the proposer must stay above to keep their proposal active
        uint256 proposalThreshold;
        /// @notice The quorum for this proposal based on gOHM total supply at the time of proposal creation
        uint256 quorumVotes;
        /// @notice The timestamp that the proposal will be available for execution, set once the vote succeeds
        uint256 eta;
        /// @notice the ordered list of target addresses for calls to be made
        address[] targets;
        /// @notice The ordered list of values (i.e. msg.value) to be passed to the calls to be made
        uint256[] values;
        /// @notice The ordered list of function signatures to be called
        string[] signatures;
        /// @notice The ordered list of calldata to be passed to each call
        bytes[] calldatas;
        /// @notice The codehash for each target contract
        bytes32[] codehashes;
        /// @notice The block at which voting begins: holders must delegate their votes prior to this block
        uint256 startBlock;
        /// @notice The block at which voting ends: votes must be cast prior to this block
        uint256 endBlock;
        /// @notice Current number of votes in favor of this proposal
        uint256 forVotes;
        /// @notice Current number of votes in opposition to this proposal
        uint256 againstVotes;
        /// @notice Current number of votes for abstaining for this proposal
        uint256 abstainVotes;
        /// @notice Flag marking whether the voting period for a proposal has been activated
        bool votingStarted;
        /// @notice Flag marking whether the proposal has been vetoed
        bool vetoed;
        /// @notice Flag marking whether the proposal has been canceled
        bool canceled;
        /// @notice Flag marking whether the proposal has been executed
        bool executed;
        /// @notice Receipts of ballots for the entire set of voters
        mapping(address => Receipt) receipts;
    }

    /// @notice Ballot receipt record for a voter
    struct Receipt {
        /// @notice Whether or not a vote has been cast
        bool hasVoted;
        /// @notice Whether or not the voter supports the proposal or abstains
        uint8 support;
        /// @notice The number of votes the voter had, which were cast
        uint256 votes;
    }

    /// @notice Possible states that a proposal may be in
    enum ProposalState {
        Pending,
        Active,
        Canceled,
        Defeated,
        Succeeded,
        Queued,
        Expired,
        Executed,
        Vetoed,
        Emergency
    }

    // --- STATE VARIABLES ---------------------------------------------------------

    /// @notice The delay before voting on a proposal may take place, once proposed, in blocks
    uint256 public votingDelay;

    /// @notice The duration of voting on a proposal, in blocks
    uint256 public votingPeriod;

    /// @notice The grace period after the voting delay through which a proposal may be activated
    uint256 public activationGracePeriod;

    /// @notice The percentage of total supply required in order for a voter to become a proposer
    /// @dev    Out of 1000
    uint256 public proposalThreshold;

    /// @notice The total number of proposals
    uint256 public proposalCount;

    /// @notice The address of the Olympus Protocol Timelock
    ITimelock public timelock;

    /// @notice The address of the Olympus governance token
    IgOHM public gohm;

    /// @notice The official record of all proposals ever proposed
    mapping(uint256 => Proposal) public proposals;

    /// @notice The latest proposal for each proposer
    mapping(address => uint256) public latestProposalIds;
}

abstract contract GovernorBravoDelegateStorageV2 is GovernorBravoDelegateStorageV1 {
    // --- STATE VARIABLES ---------------------------------------------------------

    /// @notice Modules in the Default system that are considered high risk
    /// @dev    In Default Framework, Keycodes are used to uniquely identify modules. They are a
    ///         wrapper over the bytes5 data type, and allow us to easily check if a proposal is
    ///         touching any specific modules
    mapping(Keycode => bool) public isKeycodeHighRisk;

    /// @notice Address which has veto power over all proposals
    address public vetoGuardian;

    /// @notice The central hub of the Default Framework system that manages modules and policies
    /// @dev    Used in this adaptation of Governor Bravo to identify high risk proposals
    address public kernel;
}

